namespace prts { namespace {
std::uint32_t le32(std::span<const std::uint8_t>d,std::size_t o){if(o+4>d.size())return 0;return std::uint32_t(d[o])|(std::uint32_t(d[o+1])<<8)|(std::uint32_t(d[o+2])<<16)|(std::uint32_t(d[o+3])<<24);}
std::uint64_t align4(std::uint64_t x){return (x+3u)&~std::uint64_t(3);}

enum class JT{Null,Bool,Number,String,Array,Object};
struct J {
    JT t=JT::Null;bool b=false;std::string s;std::vector<J>a;std::vector<std::pair<std::string,J>>o;
    const J* get(std::string_view k)const{for(const auto&x:o)if(x.first==k)return &x.second;return nullptr;}
};
struct JP {
    std::string_view s;std::size_t p=0,nodes=0;int depth=0;std::string error;
    bool fail(std::string x){if(error.empty())error=std::move(x);return false;}
    void ws(){while(p<s.size()&&(s[p]==' '||s[p]=='\t'||s[p]=='\r'||s[p]=='\n'))++p;}
    static int hv(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
    static void utf8(std::string&out,std::uint32_t cp){if(cp<=0x7f)out.push_back(char(cp));else if(cp<=0x7ff){out.push_back(char(0xc0|(cp>>6)));out.push_back(char(0x80|(cp&63)));}else if(cp<=0xffff){out.push_back(char(0xe0|(cp>>12)));out.push_back(char(0x80|((cp>>6)&63)));out.push_back(char(0x80|(cp&63)));}else{out.push_back(char(0xf0|(cp>>18)));out.push_back(char(0x80|((cp>>12)&63)));out.push_back(char(0x80|((cp>>6)&63)));out.push_back(char(0x80|(cp&63)));}}
    bool hex4(std::uint32_t&v){if(p+4>s.size())return fail("truncated JSON unicode escape");v=0;for(int i=0;i<4;i++){int h=hv(s[p++]);if(h<0)return fail("invalid JSON unicode escape");v=(v<<4)|std::uint32_t(h);}return true;}
    bool str(std::string&out){if(p>=s.size()||s[p++]!='"')return fail("expected JSON string");out.clear();while(p<s.size()){unsigned char c=static_cast<unsigned char>(s[p++]);if(c=='"')return true;if(c<0x20)return fail("control character in JSON string");if(c!='\\'){out.push_back(char(c));continue;}if(p>=s.size())return fail("truncated JSON escape");char e=s[p++];switch(e){case '"':out.push_back('"');break;case '\\':out.push_back('\\');break;case '/':out.push_back('/');break;case 'b':out.push_back('\b');break;case 'f':out.push_back('\f');break;case 'n':out.push_back('\n');break;case 'r':out.push_back('\r');break;case 't':out.push_back('\t');break;case 'u':{std::uint32_t cp=0;if(!hex4(cp))return false;if(cp>=0xd800&&cp<=0xdbff){if(p+2>s.size()||s[p]!='\\'||s[p+1]!='u')return fail("unpaired JSON high surrogate");p+=2;std::uint32_t lo=0;if(!hex4(lo)||lo<0xdc00||lo>0xdfff)return fail("invalid JSON surrogate pair");cp=0x10000+((cp-0xd800)<<10)+(lo-0xdc00);}else if(cp>=0xdc00&&cp<=0xdfff)return fail("unpaired JSON low surrogate");utf8(out,cp);break;}default:return fail("unknown JSON escape");}}return fail("unterminated JSON string");}
    bool value(J&v){ws();if(++nodes>1000000)return fail("JSON node limit exceeded");if(++depth>160){--depth;return fail("JSON depth limit exceeded");}auto done=[&](bool x){--depth;return x;};if(p>=s.size())return done(fail("truncated JSON value"));char c=s[p];if(c=='"'){v.t=JT::String;return done(str(v.s));}if(c=='{'){v.t=JT::Object;++p;ws();if(p<s.size()&&s[p]=='}'){++p;return done(true);}std::set<std::string>seen;while(p<s.size()){ws();std::string k;if(!str(k))return done(false);if(!seen.insert(k).second)return done(fail("duplicate JSON object key"));ws();if(p>=s.size()||s[p++]!=':')return done(fail("expected JSON colon"));J x;if(!value(x))return done(false);v.o.emplace_back(std::move(k),std::move(x));ws();if(p<s.size()&&s[p]=='}'){++p;return done(true);}if(p>=s.size()||s[p++]!=',')return done(fail("expected JSON object comma"));}return done(fail("unterminated JSON object"));}if(c=='['){v.t=JT::Array;++p;ws();if(p<s.size()&&s[p]==']'){++p;return done(true);}while(p<s.size()){J x;if(!value(x))return done(false);v.a.push_back(std::move(x));ws();if(p<s.size()&&s[p]==']'){++p;return done(true);}if(p>=s.size()||s[p++]!=',')return done(fail("expected JSON array comma"));}return done(fail("unterminated JSON array"));}if(s.substr(p,4)=="true"){p+=4;v.t=JT::Bool;v.b=true;return done(true);}if(s.substr(p,5)=="false"){p+=5;v.t=JT::Bool;v.b=false;return done(true);}if(s.substr(p,4)=="null"){p+=4;v.t=JT::Null;return done(true);}if(c=='-'||(c>='0'&&c<='9')){std::size_t b=p;if(s[p]=='-')++p;if(p>=s.size())return done(fail("truncated JSON number"));if(s[p]=='0')++p;else{if(s[p]<'1'||s[p]>'9')return done(fail("invalid JSON number"));while(p<s.size()&&std::isdigit(static_cast<unsigned char>(s[p])))++p;}if(p<s.size()&&s[p]=='.'){++p;if(p>=s.size()||!std::isdigit(static_cast<unsigned char>(s[p])))return done(fail("invalid JSON fraction"));while(p<s.size()&&std::isdigit(static_cast<unsigned char>(s[p])))++p;}if(p<s.size()&&(s[p]=='e'||s[p]=='E')){++p;if(p<s.size()&&(s[p]=='+'||s[p]=='-'))++p;if(p>=s.size()||!std::isdigit(static_cast<unsigned char>(s[p])))return done(fail("invalid JSON exponent"));while(p<s.size()&&std::isdigit(static_cast<unsigned char>(s[p])))++p;}v.t=JT::Number;v.s=std::string(s.substr(b,p-b));return done(true);}return done(fail("invalid JSON value"));}
    bool root(J&v){if(!value(v))return false;ws();return p==s.size()||fail("trailing bytes after JSON root");}
};
bool parse_json(std::string_view s,J&v,std::string&err){JP p{s};if(!p.root(v)){err=p.error;return false;}return true;}
bool jstr(const J* v,std::string&out){if(!v||v->t!=JT::String)return false;out=v->s;return true;}
bool jbool(const J* v,bool&out){if(!v||v->t!=JT::Bool)return false;out=v->b;return true;}
bool digits_u64(std::string_view s,std::uint64_t&v){if(s.empty())return false;for(char c:s)if(c<'0'||c>'9')return false;auto r=std::from_chars(s.data(),s.data()+s.size(),v);return r.ec==std::errc{}&&r.ptr==s.data()+s.size();}
bool ju64(const J* v,std::uint64_t&out){return v&&v->t==JT::Number&&digits_u64(v->s,out);}
bool valid_name(const std::string&s){return !s.empty()&&s.size()<=4096&&s!="."&&s!=".."&&s.find('/')==std::string::npos&&s.find('\\')==std::string::npos&&s.find('\0')==std::string::npos;}
bool valid_hex_sha(std::string_view s){if(s.size()!=64)return false;for(char c:s)if(!std::isxdigit(static_cast<unsigned char>(c)))return false;return true;}
std::string lower(std::string s){std::transform(s.begin(),s.end(),s.begin(),[](unsigned char c){return char(std::tolower(c));});return s;}
std::string ext_lower(const std::string&p){auto slash=p.find_last_of('/');auto dot=p.find_last_of('.');if(dot==std::string::npos||(slash!=std::string::npos&&dot<slash))return{};return lower(p.substr(dot));}
std::string base_lower(const std::string&p){auto x=p.find_last_of('/');return lower(x==std::string::npos?p:p.substr(x+1));}

bool parse_integrity(const J* v,AsarEntry&e,std::string&err){if(!v)return true;if(v->t!=JT::Object){err="ASAR integrity must be an object";return false;}std::string alg,hash;if(!jstr(v->get("algorithm"),alg)||!jstr(v->get("hash"),hash)){err="ASAR integrity algorithm/hash invalid";return false;}std::uint64_t bs=0;if(!ju64(v->get("blockSize"),bs)||!bs){err="ASAR integrity blockSize invalid";return false;}auto*b=v->get("blocks");if(!b||b->t!=JT::Array){err="ASAR integrity blocks invalid";return false;}for(const auto&x:b->a)if(x.t!=JT::String){err="ASAR integrity block hash is not a string";return false;}e.integrity_algorithm=std::move(alg);e.integrity_sha256=std::move(hash);e.integrity_block_size=bs;e.integrity_block_count=b->a.size();return true;}
struct WalkState {AsarInfo*info=nullptr;std::span<const std::uint8_t>d;std::vector<std::pair<std::uint64_t,std::uint64_t>>ranges;std::string error;};
bool walk_files(const J&files,const std::string&base,WalkState&w){if(files.t!=JT::Object){w.error="ASAR files node is not an object";return false;}for(const auto&kv:files.o){const auto&name=kv.first;const auto&v=kv.second;if(!valid_name(name)){w.error="ASAR invalid entry name: "+name;return false;}if(v.t!=JT::Object){w.error="ASAR entry is not an object: "+name;return false;}std::string path=base.empty()?name:base+'/'+name;AsarEntry e;e.path=path;auto*link=v.get("link"),*children=v.get("files"),*off=v.get("offset"),*unp=v.get("unpacked"),*sz=v.get("size");if(link){if(!jstr(link,e.link)||e.link.empty()){w.error="ASAR link target invalid: "+path;return false;}e.kind=AsarEntryKind::Link;if(unp){bool b=false;if(!jbool(unp,b)){w.error="ASAR link unpacked flag invalid: "+path;return false;}e.unpacked=b;}w.info->entries.push_back(std::move(e));++w.info->link_count;continue;}if(children){e.kind=AsarEntryKind::Directory;if(unp){bool b=false;if(!jbool(unp,b)){w.error="ASAR directory unpacked flag invalid: "+path;return false;}e.unpacked=b;}w.info->entries.push_back(e);++w.info->directory_count;if(!walk_files(*children,path,w))return false;continue;}e.kind=AsarEntryKind::File;if(!ju64(sz,e.size)){w.error="ASAR file size invalid: "+path;return false;}if(unp&&!jbool(unp,e.unpacked)){w.error="ASAR file unpacked flag invalid: "+path;return false;}if(auto*x=v.get("executable");x&&!jbool(x,e.executable)){w.error="ASAR executable flag invalid: "+path;return false;}if(!parse_integrity(v.get("integrity"),e,w.error))return false;if(!e.integrity_algorithm.empty())++w.info->integrity_count;if(e.unpacked){++w.info->unpacked_file_count;}else{std::string offset_text;if(!off||!jstr(off,offset_text)||!digits_u64(offset_text,e.offset)){w.error="ASAR packed file offset invalid: "+path;return false;}if(e.offset>w.d.size()||w.info->data_offset>w.d.size()||e.offset>w.d.size()-w.info->data_offset||e.size>w.d.size()-w.info->data_offset-e.offset){w.error="ASAR packed file range out of bounds: "+path;return false;}++w.info->packed_file_count;if(e.size)w.ranges.emplace_back(e.offset,e.size);w.info->packed_bytes=std::max(w.info->packed_bytes,e.offset+e.size);}++w.info->file_count;w.info->entries.push_back(std::move(e));}return true;}
const AsarEntry* find_file(const AsarInfo&i,std::string_view p){for(const auto&e:i.entries)if(e.kind==AsarEntryKind::File&&e.path==p)return &e;return nullptr;}
std::string norm_main(std::string s){std::replace(s.begin(),s.end(),'\\','/');while(s.rfind("./",0)==0)s.erase(0,2);while(!s.empty()&&s.front()=='/')s.erase(s.begin());if(s.empty()||s==".."||s.rfind("../",0)==0||s.find("/../")!=std::string::npos)return{};return s;}
void package_metadata(std::span<const std::uint8_t>d,AsarInfo&i){auto*e=find_file(i,"package.json");if(!e||e->unpacked||e->size>2*1024*1024)return;auto off=i.data_offset+e->offset;std::string_view text(reinterpret_cast<const char*>(d.data()+off),static_cast<std::size_t>(e->size));J root;std::string err;if(!parse_json(text,root,err)||root.t!=JT::Object)return;i.package_json_valid=true;jstr(root.get("name"),i.package_name);jstr(root.get("version"),i.package_version);std::string m;if(jstr(root.get("main"),m))i.package_main=norm_main(m);if(!i.package_main.empty()){std::array<std::string,4>c{i.package_main,i.package_main+".js",i.package_main+".json",i.package_main+"/index.js"};for(const auto&x:c)if(find_file(i,x)){i.package_main_resolved=x;break;}}}
int path_score(const AsarInfo&i,const AsarEntry&e){if(e.kind!=AsarEntryKind::File)return-1;auto p=lower(e.path),b=base_lower(e.path),ex=ext_lower(e.path);if(p=="package.json")return 1000;if(!i.package_main_resolved.empty()&&e.path==i.package_main_resolved)return 950;if(p.rfind("node_modules/",0)==0)return-1;if(b.find("preload")!=std::string::npos)return 900;if(b=="main.js"||b=="index.js"||b=="renderer.js"||b=="main.cjs"||b=="index.cjs")return 850;if(ex==".node")return 800;if(p.rfind("src/",0)==0||p.rfind("app/",0)==0)return 700;if(ex==".js"||ex==".cjs"||ex==".mjs"||ex==".ts")return 500;if(ex==".map")return 450;if(ex==".json")return 300;return-1;}
void interesting(AsarInfo&i){std::vector<std::pair<int,std::string>>x;for(const auto&e:i.entries){int s=path_score(i,e);if(s>=0)x.emplace_back(s,e.path);}std::sort(x.begin(),x.end(),[](const auto&a,const auto&b){if(a.first!=b.first)return a.first>b.first;return a.second<b.second;});std::set<std::string>seen;for(const auto&v:x)if(seen.insert(v.second).second){i.interesting_paths.push_back(v.second);if(i.interesting_paths.size()>=48)break;}}
bool safe_output_rel(std::string_view p,std::filesystem::path&out){
    out.clear();std::size_t pos=0;while(pos<p.size()){auto slash=p.find('/',pos);auto part=p.substr(pos,slash==std::string_view::npos?p.size()-pos:slash-pos);if(part.empty()||part=="."||part==".."||part.size()>255)return false;for(unsigned char c:part)if(c<0x20||c==':')return false;if(part.back()=='.'||part.back()==' ')return false;std::string low(part);std::transform(low.begin(),low.end(),low.begin(),[](unsigned char c){return char(std::tolower(c));});auto dot=low.find('.');auto stem=low.substr(0,dot);if(stem=="con"||stem=="prn"||stem=="aux"||stem=="nul"||stem=="clock$"||(stem.size()==4&&stem.rfind("com",0)==0&&stem[3]>='1'&&stem[3]<='9')||(stem.size()==4&&stem.rfind("lpt",0)==0&&stem[3]>='1'&&stem[3]<='9'))return false;out/=std::filesystem::path(std::string(part));if(slash==std::string_view::npos)break;pos=slash+1;}return !out.empty()&&!out.is_absolute()&&!out.has_root_name();}
bool write_span(const std::filesystem::path&p,std::span<const std::uint8_t>d){std::error_code ec;std::filesystem::create_directories(p.parent_path(),ec);if(ec)return false;std::ofstream o(p,std::ios::binary|std::ios::trunc);if(!o)return false;o.write(reinterpret_cast<const char*>(d.data()),static_cast<std::streamsize>(d.size()));return bool(o);}
bool verify_hash(std::span<const std::uint8_t>d,const AsarEntry&e){return lower(e.integrity_algorithm)=="sha256"&&valid_hex_sha(e.integrity_sha256)&&lower(sha256_bytes(d))==lower(e.integrity_sha256);}
}
AsarInfo detect_asar(std::span<const std::uint8_t>d,const std::filesystem::path&archive_path){AsarInfo i;i.archive_path=archive_path;if(d.size()<16){i.error="ASAR too small";return i;}if(le32(d,0)!=4){i.error="ASAR size Pickle payload is not 4 bytes";return i;}i.header_size=le32(d,4);if(i.header_size<8||i.header_size>64ull*1024*1024||i.header_size>d.size()-8){i.error="ASAR header size invalid";return i;}auto payload=le32(d,8);if(std::uint64_t(payload)+4!=i.header_size){i.error="ASAR header Pickle geometry invalid";return i;}auto slen=le32(d,12);if(std::uint64_t(4)+align4(slen)!=payload||16ull+slen>d.size()){i.error="ASAR JSON Pickle string geometry invalid";return i;}std::string_view h(reinterpret_cast<const char*>(d.data()+16),slen);J root;std::string err;if(!parse_json(h,root,err)||root.t!=JT::Object){i.error="ASAR header JSON invalid: "+err;return i;}auto*files=root.get("files");if(!files||files->t!=JT::Object){i.error="ASAR root files object missing";return i;}i.data_offset=8+i.header_size;WalkState w{&i,d};if(!walk_files(*files,"",w)){i.error=w.error;return i;}std::sort(w.ranges.begin(),w.ranges.end());std::uint64_t end=0;for(const auto&r:w.ranges){if(r.first<end){i.error="ASAR packed file ranges overlap";return i;}end=std::max(end,r.first+r.second);}if(i.data_offset+i.packed_bytes>d.size()){i.error="ASAR packed data exceeds archive";return i;}i.trailing_bytes=d.size()-(i.data_offset+i.packed_bytes);package_metadata(d,i);interesting(i);i.valid=true;return i;}
Finding asar_finding(const AsarInfo&i){Finding f;f.kind="container";f.family="Electron ASAR";if(!i.valid){f.state="FAILED";if(!i.error.empty())f.negative_evidence.push_back(i.error);return f;}f.state="CONFIRMED";f.variant=i.package_name;f.evidence.push_back("Pickle-wrapped JSON header and recursive ASAR file tree structurally validated");f.evidence.push_back("all packed file offsets/sizes are in bounds and non-overlapping");if(i.package_json_valid)f.evidence.push_back("package.json parsed from packed ASAR data");f.fields["files"]=std::to_string(i.file_count);f.fields["directories"]=std::to_string(i.directory_count);f.fields["links"]=std::to_string(i.link_count);f.fields["packed_files"]=std::to_string(i.packed_file_count);f.fields["unpacked_files"]=std::to_string(i.unpacked_file_count);f.fields["header_size"]=std::to_string(i.header_size);f.fields["data_offset"]=std::to_string(i.data_offset);f.fields["integrity_entries"]=std::to_string(i.integrity_count);if(i.trailing_bytes)f.fields["trailing_bytes"]=std::to_string(i.trailing_bytes);if(!i.package_name.empty())f.fields["package_name"]=i.package_name;if(!i.package_version.empty())f.fields["package_version"]=i.package_version;if(!i.package_main.empty())f.fields["package_main"]=i.package_main;if(!i.package_main_resolved.empty())f.fields["package_main_resolved"]=i.package_main_resolved;f.ranges.push_back({0,i.data_offset,"ASAR Pickle + JSON header"});if(i.packed_bytes)f.ranges.push_back({i.data_offset,i.packed_bytes,"ASAR packed file data"});f.suggested_actions.push_back("extract:asar");return f;}
AsarExtractResult extract_asar(std::span<const std::uint8_t>d,const AsarInfo&i,const std::filesystem::path&out,bool core_only,std::uint64_t max_output_bytes,std::uint32_t max_output_files){AsarExtractResult r;r.output_dir=out;r.core_only=core_only;if(!i.valid){r.error="invalid ASAR info";return r;}std::error_code ec;std::filesystem::create_directories(out,ec);if(ec){r.error="cannot create ASAR output directory: "+ec.message();return r;}std::set<std::string>wanted;if(core_only)wanted.insert(i.interesting_paths.begin(),i.interesting_paths.end());if(core_only&&wanted.empty()){r.success=true;return r;}std::uint64_t expected_files=0,written=0;for(const auto&e:i.entries){if(e.kind==AsarEntryKind::Link){if(!core_only)++r.links_skipped;continue;}if(core_only&&e.kind==AsarEntryKind::Directory)continue;if(core_only&&e.kind==AsarEntryKind::File&&!wanted.count(e.path))continue;std::filesystem::path rel;if(!safe_output_rel(e.path,rel)){if(e.kind==AsarEntryKind::File)++expected_files;r.warnings.push_back("ASAR extraction refused unsafe cross-platform path: "+e.path);continue;}auto dest=out/rel;if(e.kind==AsarEntryKind::Directory){std::filesystem::create_directories(dest,ec);if(!ec)++r.directories;ec.clear();continue;}++expected_files;if(r.files.size()>=max_output_files||e.size>max_output_bytes-r.output_bytes){r.budget_exhausted=true;++r.omitted_count;r.omitted_bytes=e.size>std::numeric_limits<std::uint64_t>::max()-r.omitted_bytes?std::numeric_limits<std::uint64_t>::max():r.omitted_bytes+e.size;continue;}if(e.unpacked){if(i.archive_path.empty()){r.warnings.push_back("unpacked ASAR file unavailable without archive path: "+e.path);continue;}auto src=std::filesystem::path(i.archive_path.string()+".unpacked")/std::filesystem::path(e.path);auto st=std::filesystem::symlink_status(src,ec);if(ec||st.type()!=std::filesystem::file_type::regular){ec.clear();r.warnings.push_back("unpacked ASAR sibling file missing/not regular: "+e.path);continue;}if(std::filesystem::file_size(src,ec)!=e.size||ec){ec.clear();r.warnings.push_back("unpacked ASAR sibling size mismatch: "+e.path);continue;}std::filesystem::create_directories(dest.parent_path(),ec);ec.clear();if(!std::filesystem::copy_file(src,dest,std::filesystem::copy_options::overwrite_existing,ec)||ec){ec.clear();r.warnings.push_back("failed to copy unpacked ASAR file: "+e.path);continue;}++r.unpacked_files;++written;r.output_bytes+=e.size;r.files.push_back(dest);if(lower(e.integrity_algorithm)=="sha256"&&valid_hex_sha(e.integrity_sha256)){auto h=lower(sha256_file(dest));if(h==lower(e.integrity_sha256))++r.integrity_verified;else{++r.integrity_mismatches;r.warnings.push_back("ASAR SHA256 mismatch: "+e.path);}}continue;}if(i.data_offset+e.offset>d.size()||e.size>d.size()-i.data_offset-e.offset){r.warnings.push_back("ASAR packed range became invalid: "+e.path);continue;}auto bytes=d.subspan(static_cast<std::size_t>(i.data_offset+e.offset),static_cast<std::size_t>(e.size));if(!write_span(dest,bytes)){r.warnings.push_back("failed to write ASAR file: "+e.path);continue;}++r.packed_files;++written;r.output_bytes+=e.size;r.files.push_back(dest);if(lower(e.integrity_algorithm)=="sha256"&&valid_hex_sha(e.integrity_sha256)){if(verify_hash(bytes,e))++r.integrity_verified;else{++r.integrity_mismatches;r.warnings.push_back("ASAR SHA256 mismatch: "+e.path);}}}if(r.links_skipped)r.warnings.push_back("ASAR link entries were reported but not materialized as symlinks: "+std::to_string(r.links_skipped));r.success=core_only?(written>0&&r.integrity_mismatches==0):(written==expected_files&&r.integrity_mismatches==0&&!r.budget_exhausted);if(!r.success)r.error=core_only?"no complete ASAR core artifact set was materialized":"not all ASAR files were extracted/validated";return r;}
}
